import{_ as r,l,o as e,c as n,v as o,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"点定位","description":"","frontmatter":{"title":"点定位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/point-location.md","filePath":"cs/point-location.md","lastUpdated":1789023840000}'),h={name:"cs/point-location.md"};function u(_,a,m,k,A,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="点定位" tabindex="-1">点定位 <a class="header-anchor" href="#点定位" aria-label="Permalink to &quot;点定位&quot;">​</a></h1><div class="epigraph"><p>平面剖分成面后，询问点落在哪一面：梯形图或 Kirkpatrick 层次，$O(n)$ 空间 $O(\\log n)$ 查询。</p><footer>—— 据 Kirkpatrick, Optimal Search in Planar Subdivisions, 1983；Mulmuley、Seidel 随机增量梯形图整理</footer></div><p>上一课<a href="/cs/voronoi-delaunay">Voronoi 与 Delaunay</a>给出剖分。缺口是查询：点 \\(q\\) 在哪个面/哪条 Delaunay 边的哪侧。朴素 \\(O(n)\\) 走。本课点定位结构。不重写 Fortune。后课几何精度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>梯形图：过每个顶点作竖线直到撞边，面变梯形。随机增量期望 \\(O(n)\\) 大小、\\(O(\\log n)\\) 历史 DAG 查询。Kirkpatrick：独立集收缩层次，\\(\\log\\) 层。步行（沿 Delaunay 走）实践快但最坏差。</p><p>缺口是数据结构，不是再三角化。</p><h3 id="不是最近邻本身" tabindex="-1">不是最近邻本身 <a class="header-anchor" href="#不是最近邻本身" aria-label="Permalink to &quot;不是最近邻本身&quot;">​</a></h3><p>最近站点可用 Voronoi 定位，或 k-d 树。本课一般剖分。k-d 树是正交，点名。</p><p><span class="marginnote">Kirkpatrick 1983。CGAL 实现随机梯形图。后课鲁棒性：定位依赖谓词符号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理剖分。询问沿 DAG 或层次下降。动态插入更重（随机增量在线）。</p>',11)),(e(),s(c,null,{default:t(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E5%B9%B3%E9%9D%A2%E5%89%96%E5%88%86%22%5D%20--%3E%20TRAP%5B%22%E6%A2%AF%E5%BD%A2%E5%9B%BE%20%2F%20%E5%B1%82%E6%AC%A1%22%5D%0A%20%20TRAP%20--%3E%20Q%5B%22O(log%20n)%20%E7%82%B9%E5%AE%9A%E4%BD%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与扫描线：梯形图常随机增量不是从左扫一次完。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每层面数减常因子，查询下降对数。历史 DAG 记录「被谁切开」。与二叉搜索树：几何键是区域包含。与半平面：对偶可把某些定位变成凸包切。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维点定位。动态删点不写。后课默认：静态剖分 \\(O(\\log n)\\) 定位。下一课几何精度与鲁棒性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剖分查询用梯形图或 Kirkpatrick。</li><li>\\(O(n)\\) 空间、\\(O(\\log n)\\) 查询。</li><li>步行实用、最坏弱。</li><li>出处：Kirkpatrick, 1983；随机增量梯形图。</li></ul>',7))])}const T=r(h,[["render",u]]);export{D as __pageData,T as default};
